import React, { Component } from 'react'
import { JobStyleWrapper } from './career.style'
import JobSearch from './JobSearchBar'
import { Row, Col, Breadcrumb, Card } from 'antd'
import AppFooter from '../../../components/Footer/footer'
import { imageUrls, Section5Content } from './content'
import PropTypes from 'prop-types'
const { jobType, category } = imageUrls
class JobDetailComponent extends Component {
  constructor (props) {
    super(props)
    this.state = {
      content: ''
    }
  }
  componentWillMount () {
    const { location } = this.props
    const { state } = location
    if (state === undefined) {
      this.homePage()
      window.location.reload()
    }
  }

  applyFormPage = data => {
    this.props.history.push('/career/form', { ...data })
  };
  categoryPage = () => {
    this.props.history.push({
      pathname: '/career/job-category',
      state: Section5Content.filter(item => item.positionsArray.length > 0)
    })
  }
  homePage = () => {
    this.props.history.push({
      pathname: '/career'
    })
  }
  jobDescriptionPage = (selectedPosition) => {
    let data = {}
    Section5Content.map((item, index) => {
      let { positionsArray } = item
      positionsArray.map(filterData => {
        if (filterData.position === selectedPosition.position) {
          data = {
            index,
            item,
            filterData
          }
        }
      })
    })
    this.props.history.push({
      pathname: '/career/vacancy-list/job-description',
      state: { ...data }
    })
  }
  render () {
    const { location, history } = this.props
    let filteredContent = location.state
    return (
      <div>
        <JobStyleWrapper>
          <JobSearch history={history} showBackground />
          <Row className='sectionDiv'>
            <Col span={24} className='marginB20'>
              <Breadcrumb className='padding20 font-size17'>
                <Breadcrumb.Item>
                  <span onClick={() => this.homePage()}>
                    Career
                  </span>
                </Breadcrumb.Item>
                <Breadcrumb.Item>
                  <span onClick={() => this.categoryPage()}>
                    Jobs
                  </span>
                </Breadcrumb.Item>
                {
                  filteredContent.category &&
                  <Breadcrumb.Item>
                    <span className='text-yellow'>{filteredContent.category}</span>
                  </Breadcrumb.Item>
                }
              </Breadcrumb>
            </Col>
            <Col span={24} className='flex-container marginB20 mobileDesignFix'>
              <div className='padding20'>
                <img
                  src={filteredContent.logo}
                  alt='technology'
                  className='jobDetail-main-image'
                />
              </div>
              <div className='padding20'>
                <h2 className='text-yellow'>{filteredContent.category}</h2>
              </div>
            </Col>
            <Col span={24} className='marginB20 flex-wrap'>
              {
                filteredContent.positionsArray.map((item, index) => (
                  <Col xl={8} lg={8} md={12} sm={12} xs={24} className='padding20'>
                    <Card className='custom-card card-no-padding body-flex'>
                      <div className='padding24 no-paddingB'>
                        <h3 className='text-yellow'>{item.position}</h3>
                        <ul className='custom-list'>
                          <li>{item.text}</li>
                        </ul>
                      </div>
                      <div className='padding24 marginT-auto no-paddingT'>
                        <hr className='custon-hr' />
                        <div className='flex-container'>
                          <div className='padding5'>
                            <img
                              src={category}
                              alt='location'
                              className='display_inlineB smaller-side-image'
                            />
                            <small className='display_inlineB color-fade font-mobile-13'>
                              {item.jobLocation}
                            </small>
                          </div>
                          <div className='padding5'>
                            <img
                              src={jobType}
                              alt='type'
                              className='display_inlineB smaller-side-image'
                            />
                            <small className='display_inlineB color-fade font-mobile-13'>
                              {item.jobSpan}
                            </small>
                          </div>
                        </div>
                      </div>
                      <Row type='flex'>
                        <Col
                          span={12}
                          className='text-center job-detail-button button-detail'
                          onClick={() => this.jobDescriptionPage(item)}>
                          See Details
                        </Col>
                        <Col
                          span={12}
                          className='text-center job-detail-button button-apply'
                          onClick={() => this.applyFormPage(item)}
                        >
                          Apply
                        </Col>
                      </Row>
                    </Card>
                  </Col>
                ))}
            </Col>
            {/* <Col span={24} className='marginB20 text-center'>
            <span className='text-yellow see-more-box'>
              See 3 More
               <span className='bottom-arrow'></span>
            </span>
          </Col> */}
          </Row>
        </JobStyleWrapper>
        <AppFooter />
      </div>
    )
  }
}

JobDetailComponent.propTypes = {
  content: PropTypes.array.isRequired,
  sectedContentData: PropTypes.array.isRequired,
  routingFunction: PropTypes.func.isRequired
}

export default JobDetailComponent
